  select md5(prosrc),pg_get_functiondef(oid) into body_hash,definition from pg_proc where oid=to_regprocedure(spec->>'signature');
  if body_hash=spec->>'before' then continue;end if;
  if body_hash is distinct from spec->>'after' then raise exception 'yash_channel_rollback_drift: %',spec->>'signature' using errcode='55000';end if;
  for replacement in select value from jsonb_array_elements(spec->'replacements') loop
   if (length(definition)-length(replace(definition,replacement->>1,'')))/length(replacement->>1)<>1
