   definition:=replace(definition,replacement->>1,replacement->>0);
  end loop;
  execute definition;
  if (select md5(prosrc) from pg_proc where oid=to_regprocedure(spec->>'signature'))<>spec->>'before'
  then raise exception 'yash_channel_rollback_after_drift: %',spec->>'signature' using errcode='55000';end if;
 end loop;
